ov(a){return"\u0639\u0636\u0648 \u0645\u0646\u0630 "+a},
u9(a){return"\u0627\u0644\u0625\u0635\u062f\u0627\u0631 v"+a+" \u0645\u062a\u0627\u062d"},
pr(a){return"\u062a\u062d\u062f\u064a\u062b v"+a},
yL(a,b){return"\u062a\u062d\u062f\u064a\u062b "+(b?"\u062a\u062c\u0631\u064a\u0628\u064a":"\u062c\u062f\u064a\u062f")+": v"+a},
Bj(a){return""+a+" \u0639\u0646\u0635\u0631"},
uJ(a){return"\u0643\u0644 "+a+" \u0633\u0627\u0639\u0629"},
uO(a){return a===0?"\u0644\u0627 \u062a\u0648\u062c\u062f \u062a\u0634\u063a\u064a\u0644\u0627\u062a \u062c\u062f\u064a\u062f\u0629":"\u062a\u0645 \u0627\u0644\u0639\u062b\u0648\u0631 \u0639\u0644\u0649 "+a+" \u062a\u0634\u063a\u064a\u0644\u0629 \u062c\u062f\u064a\u062f\u0629"},
DA(a){return"\u0646\u064f\u0634\u0631 \u0641\u064a "+a},
vH(a){return"\u0625\u0632\u0627\u0644\u0629 @"+a+" \u0645\u0646 \u062d\u0633\u0627\u0628\u0627\u062a\u0643\u061f"},
vt(a){return"\u062a\u0645\u062a \u0625\u0636\u0627\u0641\u0629 @"+a+" \u0628\u0646\u062c\u0627\u062d."},
vG(a,b){return"\u062d\u0633\u0627\u0628\u0627\u062a\u064a ("+a+"/"+b+")"},
